-- Week 10: project planning, iteration, and a first look at recursion.
DO $$
DECLARE c uuid; m integer;
BEGIN
 SELECT id INTO c FROM public.courses WHERE slug='python-foundations';
 IF c IS NULL THEN RAISE EXCEPTION 'Python Foundations course must exist'; END IF;
 INSERT INTO public.modules(course_id,month_number,title,tagline,description,capstone_title,is_free,order_index,status)
 VALUES(c,10,'Build and Explain a Python Project','Week 10 · Sessions 1–5','Plan a small useful program, build it in steps, test it, and explain the result.','A Beginner Python Project',false,10,'published')
 ON CONFLICT(course_id,month_number,order_index) DO UPDATE SET title=EXCLUDED.title,tagline=EXCLUDED.tagline,description=EXCLUDED.description,capstone_title=EXCLUDED.capstone_title,is_free=EXCLUDED.is_free,status=EXCLUDED.status RETURNING id INTO m;
 WITH d(n,title,analogy,body,q,opts,ans,why) AS (VALUES
 (1,'Choose a Small Real Problem','A community event starts with a clear purpose and manageable plan.','## Goal\nChoose a useful project with a small first version.\n\n## Plain explanation\nA final project is a program you design to solve a problem you choose. Start by naming who will use it and what they need. Decide what information goes in, what the program will do, and what result comes out. Keep the first version small: a quiz, reading log, simple budget helper, or class attendance list can be enough.\n\n## Plan\nWrite one sentence describing the problem, then list two to four features for the first version.','Why keep the first project version small?','["It is easier to finish and improve in steps", "Small programs cannot have bugs", "A project should not solve a problem"]'::jsonb,0,'A manageable first version can be completed, tested, and improved without becoming overwhelming.'),
 (2,'Break the Program into Functions','A large task becomes easier when divided into clear steps.','## Goal\nOrganize the project into functions with clear jobs.\n\n## Plain explanation\nA function is a named group of instructions that does one job. A project might have `get_choice`, `calculate_total`, and `show_result`. Clear function names make the program easier to read and help you change one part without rewriting everything. Start with the smallest working program, then add features one at a time.','What makes a function easier to understand?','["A clear name and one main job", "Putting the entire project on one line", "Using the same name for every function"]'::jsonb,0,'A clear name and focused task help a learner understand and reuse a function.'),
 (3,'Test and Debug the Project','Check ordinary cases and the edge of each rule before relying on a result.','## Goal\nUse examples and tests to find and fix project problems.\n\n## Plain explanation\nRun the program with ordinary input, boundary values, and invalid input. Compare the actual result with what you expected. When something fails, reproduce it with the same input, inspect the relevant function, change one thing, then run the example again. Reuse `try` and `except` for expected input problems and `assert` or pytest for repeatable checks where available.','What is a useful first debugging step?','["Repeat the problem with the same input", "Change many unrelated lines at once", "Ignore the output"]'::jsonb,0,'Reproducing the problem gives a reliable example to inspect while debugging.'),
 (4,'Demonstrate and Explain the Program','A short demonstration shows how a tool helps its user.','## Goal\nPrepare a clear explanation of the project and its limits.\n\n## Plain explanation\nShow the problem your program addresses, demonstrate one normal run, and explain the important code choices. Say what the program does not handle yet. Naming a limitation is useful because it identifies what a future version could improve. Do not include passwords, API keys, or private personal information in a demonstration.','What should a project demonstration include?','["The problem, a working example, and a clear explanation", "Only a list of error messages", "A claim that the program has no limits"]'::jsonb,0,'A useful demonstration connects the code to the problem and shows how the program behaves.'),
 (5,'Understand Recursion with a Countdown','Nested boxes lead to a smallest box, then the steps return outward.','## Goal\nIdentify the stopping case in a recursive function.\n\n## Plain explanation\nRecursion happens when a function calls itself to solve a smaller version of a problem. It needs a base case: the condition that stops the calls. Without it, the function may call itself forever until Python reports an error. In a countdown, the base case is reaching zero. Trace a tiny example by hand before running it. Recursion is a new concept, but it does not need to be used in every final project.\n\n## Example\n```python\ndef countdown(number):\n    if number == 0:  # base case: stop\n        print("Done")\n    else:\n        print(number)\n        countdown(number - 1)\n\ncountdown(3)\n```','What prevents the recursive countdown from continuing forever?','["The base case at zero", "The function name", "The print statement"]'::jsonb,0,'The base case says what to do at zero and prevents another recursive call.')
 ), ins AS (
 INSERT INTO public.sessions(module_id,session_number,title,analogy_physical,content_markdown,starter_code,hints,xp_reward,order_index,duration_minutes,quick_check)
 SELECT m,n,title,analogy,replace(replace(replace(body,'A project might have `get_choice`, `calculate_total`, and `show_result`. Clear function names make the program easier to read and help you change one part without rewriting everything.','A project might have `get_choice`, `calculate_total`, and `show_result`. Clear function names make the program easier to read and help you change one part without rewriting everything. The lecture also introduces constants, docstrings, and type hints. A type hint describes the intended kind of value; it does not automatically convert or validate it.'),'## Plain explanation\nShow the problem your program addresses, demonstrate one normal run, and explain the important code choices. Say what the program does not handle yet. Naming a limitation is useful because it identifies what a future version could improve. Do not include passwords, API keys, or private personal information in a demonstration.','## Plain explanation\nShow the problem your program addresses, demonstrate one normal run, and explain the important code choices. The final project also asks for a README and short video demonstration. Say what the program does not handle yet. Naming a limitation is useful because it identifies what a future version could improve. Do not include passwords, API keys, or private personal information in a demonstration.'),chr(92)||'n',chr(10)),replace('# Start with a small program plan\n',chr(92)||'n',chr(10)),'["Name the user and the problem.","Build one feature at a time.","Try ordinary and invalid inputs."]'::jsonb,50,n,15,jsonb_build_object('question',q,'options',opts) FROM d
 ON CONFLICT(module_id,session_number) DO UPDATE SET title=EXCLUDED.title,analogy_physical=EXCLUDED.analogy_physical,content_markdown=EXCLUDED.content_markdown,starter_code=EXCLUDED.starter_code,hints=EXCLUDED.hints,xp_reward=EXCLUDED.xp_reward,order_index=EXCLUDED.order_index,duration_minutes=EXCLUDED.duration_minutes,quick_check=EXCLUDED.quick_check RETURNING id,session_number
 ) INSERT INTO private.session_quick_check_answers(session_id,correct_option,explanation) SELECT ins.id,d.ans,d.why FROM ins JOIN d ON d.n=ins.session_number ON CONFLICT(session_id) DO UPDATE SET correct_option=EXCLUDED.correct_option,explanation=EXCLUDED.explanation;
END $$;
